import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

describe('WatchlistStore: seen field', () => {
  const movie: TmdbMovie = {
    id: 42,
    title: 'Sunset Boulevard',
    release_date: '1950-08-25',
    poster_path: null,
    overview: 'A screenwriter draws a faded silent film star.',
  };

  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
  });

  it('adds items with seen false and no watched property', () => {
    const store = new WatchlistStore();
    store.add(movie);
    const items = store.items();
    expect(items).toHaveLength(1);
    expect(items[0].seen).toBe(false);
    expect('watched' in items[0]).toBe(false);
  });

  it('toggleWatched flips the seen flag and updates watchedCount', () => {
    const store = new WatchlistStore();
    store.add(movie);
    expect(store.watchedCount()).toBe(0);
    store.toggleWatched(42);
    expect(store.items()[0].seen).toBe(true);
    expect(store.watchedCount()).toBe(1);
    store.toggleWatched(42);
    expect(store.items()[0].seen).toBe(false);
    expect(store.watchedCount()).toBe(0);
  });

  it('persists and reloads items with the seen field', () => {
    const store = new WatchlistStore();
    store.add(movie);
    store.toggleWatched(42);
    const reloaded = new WatchlistStore();
    const items = reloaded.items();
    expect(items).toHaveLength(1);
    expect(items[0].seen).toBe(true);
    expect('watched' in items[0]).toBe(false);
  });
});

